{
  "一字马姿势": {
    "基本定义": "'{{intimate-women}}'双腿完全劈开成一字形，展露骚穴的极度淫荡姿势",
    "核心特征": [
      "双腿完全撑开，呈180度直线",
      "骚穴完全暴露，方便{{npc-men}}插入",
      "体现极度柔韧性和淫荡程度"
    ],
    "基本姿势变种": {
      "站立一字马": {
        "描述": "'{{intimate-women}}'双脚分开站立，一条腿高举过头顶",
        "优点": [
          "方便{{npc-men}}站立插入，可深入到子宫",
        ]
      },
      "躺地一字马": {
        "描述": "'{{intimate-women}}'仰躺在地，双腿完全劈开贴地",
        "优点": [
          "'{{intimate-women}}'可以完全放松，承受长时间肏弄",
          "骚穴和屁眼同时暴露，方便多根鸡巴同时插入",
        ]
      },
      "倒立一字马": {
        "描述": "'{{intimate-women}}'双手撑地倒立，双腿在空中劈开",
        "优点": [
          "{{npc-men}}可居高临下插入，角度刁钻",
          "'{{intimate-women}}'头部正对{{npc-men}}的生殖器，方便舔舐阴囊"
        ]
      },
      "悬空一字马": {
        "描述": "'{{intimate-women}}'双手扶墙或攀附其他物体，双腿在空中劈开",
        "优点": [
          "全身肌肉紧绷，骚穴更加紧致",
          "腾出双手可以掰开骚穴，方便更深入插入",
        ]
      }
    },
    "进阶玩法": {
      "多人一字马": {
        "描述": "多位{{npc-men}}同时插入菩萨的各个肉穴",
        "细节": [
          "一根粗大鸡巴插入骚穴，一根插入屁眼",
          "菩萨双手各握一根鸡巴撸动",
          "一根鸡巴插入'{{intimate-women}}'口中进行深喉"
        ]
      },
      "震动棒一字马": {
        "描述": "在保持一字马姿势的同时，体内塞满各种淫具",
        "细节": [
          "骚穴和屁眼各插入一根粗大震动棒",
          "乳头上贴着跳蛋，持续刺激",
          "阴蒂夹上带铃铛的阴蒂夹"
        ]
      },
      "公开一字马": {
        "描述": "在公共场合保持一字马姿势",
        "场景": [
          "在庙会上当众表演一字马，任人参拜亵玩",
          "在繁华街头保持一字马姿势乞讨，接受路人的施舍和侵犯",
          "在神圣法会上一边开腿一边讲经，彰显反差"
        ]
      },
      "精液灌注一字马": {
        "描述": "保持一字马姿势接受大量内射",
        "细节": [
          "骚穴和屁眼同时被内射，灌满精液",
          "保持姿势不动，让精液自然流出，形成淫靡景象",
          "用骚穴和屁眼交替收缩，像挤牛奶一样排出精液"
        ]
      }
    },
    "极限挑战": {
      "持久一字马": "保持一字马姿势数小时不动，期间持续承受{{npc-men}}的蹂躏",
      "加重一字马": "双腿绑上沙袋或重物，增加难度的同时承受肏弄",
      "悬空旋转一字马": "被绳索吊起，保持一字马姿势在空中缓慢旋转，接受四面八方的插入"
    ]
  }
}
